        cap = g(instance, "vehicle_capacity")
    if cap is None:
        cap = 0

    dem = g(instance, "demands")
    if dem is None:
        dem = g(instance, "demand")
    if dem is not None:
        dem = list(dem)

    depot = g(instance, "depot", 0)
    if isinstance(depot, (list, tuple)):
        depot = depot[0] if depot else 0

    customers = g(instance, "customers")
    if customers is None:
        n = g(instance, "n")
        if n is None:
            if dem is not None:
                n = len(dem) - 1
            else:
                n = len(coords) - 1 if coords is not None else 0
        customers = list(range(1, int(n) + 1))
    else:
        customers = list(customers)

    if dem is None:
        m = max(customers) if customers else 0
        dem = [0] * (m + 1)
    elif len(dem) <= max(customers, default=0):
        dem = dem + [0] * (max(customers) + 1 - len(dem))

    if cap <= 0:
        cap = sum(dem[c] for c in customers) if customers else 1

    def d(i, j):
        if dist is not None:
            return dist[i][j]
        xi, yi = coords[i]
        xj, yj = coords[j]
        a = xi - xj
        b = yi - yj
        return (a * a + b * b) ** 0.5

    def load(route):
        s = 0
        for c in route:
            s += dem[c]
        return s

    def cost(route):
        if not route:
            return 0.0
        t = d(depot, route[0])
        for i in range(len(route) - 1):
            t += d(route[i], route[i + 1])
        return t + d(route[-1], depot)

    def best_insert(route, c):
        best = None
        pos = 0
        for i in range(len(route) + 1):
            a = depot if i == 0 else route[i - 1]
            b = depot if i == len(route) else route[i]
            inc = d(a, c) + d(c, b) - d(a, b)
            key = (inc, i)
            if best is None or key < best:
                best = key
                pos = i
        return pos

    def two_opt(route):
        r = route[:]
        n = len(r)
        if n < 4:
            return r
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, n):
                    c = r[j]
                    e = depot if j == n - 1 else r[j + 1]
                    if d(a, c) + d(b, e) + 1e-12 < d(a, b) + d(c, e):
                        r[i:j + 1] = r[i:j + 1][::-1]
                        improved = True
                        break
                if improved:
                    break
        return r

    unv = set(customers)
    routes = []
    dep = {}
    if coords is not None:
        dx, dy = coords[depot]
        for c in customers:
            x, y = coords[c]
            dep[c] = ((x - dx) ** 2 + (y - dy) ** 2) ** 0.5
    else:
        for c in customers:
            dep[c] = d(depot, c)

    while unv:
        seed = None
        sk = None
        for c in unv:
            k = (dep[c], dem[c], -c)
            if sk is None or k > sk:
                sk = k
                seed = c
        r = [seed]
        unv.remove(seed)
        cur = dem[seed]
        while True:
            last = r[-1]
            best = None
            bc = None
            for c in unv:
                if cur + dem[c] > cap:
                    continue
                k = (d(last, c) + d(c, depot) - d(last, depot), -dem[c], d(last, c), c)
                if best is None or k < best:
                    best = k
                    bc = c
            if bc is None:
                break
            r.append(bc)
            unv.remove(bc)
            cur += dem[bc]
        routes.append(two_opt(r))

    changed = True
    while changed:
        changed = False

        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                li = load(ri)
                lj = load(rj)
                for a in range(len(ri)):
                    ca = ri[a]
                    for b in range(len(rj)):
                        cb = rj[b]
                        if li - dem[ca] + dem[cb] > cap or lj - dem[cb] + dem[ca] > cap:
                            continue
                        nri = ri[:a] + [cb] + ri[a + 1:]
                        nrj = rj[:b] + [ca] + rj[b + 1:]
                        if cost(nri) + cost(nrj) + 1e-12 < cost(ri) + cost(rj):
                            routes[i] = two_opt(nri)
                            routes[j] = two_opt(nrj)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break

        if changed:
            continue

        for i in range(len(routes)):
            ri = routes[i]
            li = load(ri)
            for p in range(len(ri)):
                c = ri[p]
                rest = ri[:p] + ri[p + 1:]
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if load(rj) + dem[c] > cap:
                        continue
                    base = cost(ri) + cost(rj)
                    for ins in range(len(rj) + 1):
                        nrj = rj[:ins] + [c] + rj[ins:]
                        if cost(rest) + cost(nrj) + 1e-12 < base:
                            routes[i] = two_opt(rest) if rest else []
                            routes[j] = two_opt(nrj)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break

        routes = [r for r in routes if r]

    seen = set()
    out = []
    for r in routes:
        nr = []
        ld = 0
        for c in r:
            if c not in seen:
                nr.append(c)
                seen.add(c)
                ld += dem[c]
        if nr:
            out.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        for r in out:
            if load(r) + dem[c] <= cap:
                pos = best_insert(r, c)
                r.insert(pos, c)
                placed = True
                break
        if not placed:
            out.append([c])

    fixed = []
    for r in out:
        cur = []
        ld = 0
        for c in r:
            if ld + dem[c] <= cap:
                cur.append(c)
                ld += dem[c]
            else:
                if cur:
                    fixed.append(cur)
                cur = [c]
                ld = dem[c]
        if cur:
            fixed.append(cur)

    return fixed
